<script>
const wishlistStorageKey='luvora-wishlist';
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));
const readWishlist=()=>{try{return JSON.parse(localStorage.getItem(wishlistStorageKey)||'[]')}catch{return[]}};
function saveWishlist(items){localStorage.setItem(wishlistStorageKey,JSON.stringify(items));renderWishlist()}
function renderWishlist(){const items=readWishlist();const grid=document.getElementById('product-grid');document.getElementById('display-count').textContent=items.length;document.getElementById('saved-count-crumb').textContent=String(items.length).padStart(2,'0');document.getElementById('stat-total-items').textContent=`${items.length} Pieces`;document.getElementById('stat-total-price').textContent='LKR '+items.reduce((sum,item)=>sum+Number(item.price||0),0).toLocaleString('en-LK');document.getElementById('wishlist-active-view').classList.toggle('hidden',items.length===0);document.getElementById('wishlist-empty-view').classList.toggle('hidden',items.length!==0);grid.innerHTML=items.map(item=>{const href=String(item.url||'/shop').startsWith('/')?item.url:'/shop';const image=item.image?`<img class="w-full h-full object-cover" src="${escapeHtml(item.image)}" alt="${escapeHtml(item.name)}">`:'<div class="w-full h-full flex items-center justify-center text-secondary"><span class="material-symbols-outlined text-5xl">image</span></div>';return `<article class="wishlist-item flex flex-col bg-surface-container-lowest rounded-xl overflow-hidden shadow-sm"><div class="relative aspect-[3/4] bg-surface-container-low">${image}<button class="absolute top-3 right-3 w-9 h-9 rounded-full bg-surface-container-lowest/80 text-error" data-remove-id="${escapeHtml(item.id)}" aria-label="Remove from wishlist"><span class="material-symbols-outlined">favorite</span></button></div><div class="p-space-md"><h2 class="font-headline-sm text-headline-sm"><a href="${escapeHtml(href)}">${escapeHtml(item.name)}</a></h2><p class="font-headline-sm font-bold mt-space-sm">LKR ${Number(item.price||0).toLocaleString('en-LK')}</p><a class="mt-space-md block rounded-full bg-primary px-space-md py-space-xs text-center text-on-primary" href="${escapeHtml(href)}">View product</a></div></article>`}).join('');document.querySelectorAll('[data-wishlist-count]').forEach(el=>el.textContent=items.length)}
document.addEventListener('click',event=>{const remove=event.target.closest('[data-remove-id]');if(remove)saveWishlist(readWishlist().filter(item=>String(item.id)!==String(remove.dataset.removeId)))});
function clearAllItems(){saveWishlist([])}function showToast(message){const toast=document.getElementById('toast');if(!toast)return;document.getElementById('toast-msg').textContent=message;toast.classList.remove('translate-y-20','opacity-0');setTimeout(()=>toast.classList.add('translate-y-20','opacity-0'),2200)}
function restoreWishlistMock(){window.location.href="{{ route('shop.index') }}"}
function toggleEmptyState(){document.getElementById('wishlist-empty-view').classList.toggle('hidden')}
function toggleShareModal(show){document.getElementById('share-modal').classList.toggle('hidden',!show);document.getElementById('share-modal').classList.toggle('flex',show)}
function copyShareUrl(){navigator.clipboard?.writeText(location.href)}
function reorderWishlist(order){const items=readWishlist();if(order==='price-asc')items.sort((a,b)=>a.price-b.price);if(order==='price-desc')items.sort((a,b)=>b.price-a.price);saveWishlist(items)}
function addAllToCart(){window.location.href="{{ route('cart.index') }}"}
renderWishlist();
</script></main><footer class="w-full bg-surface-container-low mt-space-xl pt-space-xl pb-space-lg shadow-[0_1px_8px_rgba(0,0,0,0.02)]"><div class="max-w-7xl mx-auto px-gutter lg:px-gutter-lg"><div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-gutter-lg pb-space-xl"><div class="lg:col-span-2 pr-space-lg"><div class="flex items-center gap-space-sm mb-space-md"><span class="font-headline-md text-headline-md tracking-tight text-on-surface">Luvora</span></div><p class="font-body-sm text-body-sm text-on-surface-variant mb-space-md leading-relaxed">The premier high-fashion sanctuary of Ceylon. Curating world-class island artisanal craftsmanship, ethical gems, and international contemporary collections for refined global wardrobes.</p><div class="space-y-space-xs"><p class="font-label-sm text-label-sm uppercase tracking-wider text-secondary">Join the Luvora Society</p><div class="flex items-center gap-space-xs max-w-sm"><input class="w-full bg-surface-container-lowest border border-outline-variant rounded-full px-space-md py-space-xs font-body-sm text-body-sm text-on-surface focus:outline-none focus:border-primary" placeholder="Enter your email..." type="email"/><a href="{{ route('newsletter') }}" class="bg-on-background text-surface-container-lowest font-label-md text-label-md uppercase px-space-md py-space-xs rounded-full hover:bg-primary transition-colors shrink-0">Join</a></div></div></div><div><h3 class="font-label-sm text-label-sm uppercase tracking-wider text-on-surface mb-space-md">Shop</h3><ul class="space-y-space-xs"><li class="font-body-sm text-body-sm text-on-surface-variant hover:text-primary transition-colors"><a data-path="women" href="{{ route('shop.index') }}">Women's Couture</a></li><li class="font-body-sm text-body-sm text-on-surface-variant hover:text-primary transition-colors"><a data-path="men" href="{{ route('shop.index') }}">Men's Tailoring</a></li><li class="font-body-sm text-body-sm text-on-surface-variant hover:text-primary transition